use super::*;

const MANAGED_SCHEDULE_EXPORT_HEADER: &str =
    "# Generated by Zelyra setup. Re-run `zelyra setup --schema` to refresh.";

pub(super) fn task_command(mut args: impl Iterator<Item = String>) -> ExitCode {
    let Some(action) = args.next() else {
        task_usage();
        return ExitCode::from(2);
    };
    match action.as_str() {
        "list" => {
            let Some(path) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let json = match args.next().as_deref() {
                None => false,
                Some("--json") => true,
                _ => {
                    task_usage();
                    return ExitCode::from(2);
                }
            };
            if args.next().is_some() {
                task_usage();
                return ExitCode::from(2);
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            if json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&json!({
                        "schema_version": 1,
                        "commands": program.commands.iter().map(|command| {
                            let function = program.functions.iter().find(|function| function.name == command.handler);
                            json!({
                                "name": command.name,
                                "handler": command.handler,
                                "description": command.description,
                                "source_line": command.span.line,
                                "parameters": function.map(|function| function.params.iter().map(|parameter| json!({"name": parameter.name, "type": parameter.ty.to_string()})).collect::<Vec<_>>()).unwrap_or_default(),
                            })
                        }).collect::<Vec<_>>(),
                    }))
                    .expect("task inventory JSON is serializable")
                );
            } else if program.commands.is_empty() {
                println!("No commands declared in {path}");
            } else {
                for command in &program.commands {
                    let function = program
                        .functions
                        .iter()
                        .find(|function| function.name == command.handler);
                    let parameters = function
                        .map(|function| {
                            function
                                .params
                                .iter()
                                .map(|parameter| format!("{}: {}", parameter.name, parameter.ty))
                                .collect::<Vec<_>>()
                                .join(", ")
                        })
                        .unwrap_or_default();
                    println!("{}({}) -> {}", command.name, parameters, command.handler);
                    if let Some(description) = &command.description {
                        println!("  {description}");
                    }
                }
            }
            ExitCode::SUCCESS
        }
        "run" => {
            let Some(path) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let Some(name) = args.next() else {
                task_usage();
                return ExitCode::from(2);
            };
            let mut entry_args = None;
            let mut max_steps = None;
            while let Some(argument) = args.next() {
                match argument.as_str() {
                    "--args" if entry_args.is_none() => match args.next() {
                        Some(value) => entry_args = Some(value),
                        None => {
                            task_usage();
                            return ExitCode::from(2);
                        }
                    },
                    "--max-steps" if max_steps.is_none() => match args.next() {
                        Some(value) => max_steps = Some(value),
                        None => {
                            task_usage();
                            return ExitCode::from(2);
                        }
                    },
                    _ => {
                        task_usage();
                        return ExitCode::from(2);
                    }
                }
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            let Some(command) = program.commands.iter().find(|command| command.name == name) else {
                eprintln!("error[E-TASK-002]: command `{name}` was not declared in `{path}`");
                return ExitCode::from(2);
            };
            let mut process = match env::current_exe() {
                Ok(executable) => Command::new(executable),
                Err(error) => {
                    eprintln!("error[E-TASK-003]: cannot locate Zelyra executable: {error}");
                    return ExitCode::from(1);
                }
            };
            process.args(["run", &path, "--entry", &command.handler]);
            if let Some(entry_args) = entry_args {
                process.args(["--entry-args", &entry_args]);
            }
            if let Some(max_steps) = max_steps {
                process.args(["--max-steps", &max_steps]);
            }
            match process.status() {
                Ok(status) if status.success() => ExitCode::SUCCESS,
                Ok(status) => ExitCode::from(
                    status
                        .code()
                        .and_then(|code| u8::try_from(code).ok())
                        .unwrap_or(1),
                ),
                Err(error) => {
                    eprintln!("error[E-TASK-003]: could not start command `{name}`: {error}");
                    ExitCode::from(1)
                }
            }
        }
        _ => {
            task_usage();
            ExitCode::from(2)
        }
    }
}

pub(super) fn schedule_command(mut args: impl Iterator<Item = String>) -> ExitCode {
    let Some(action) = args.next() else {
        schedule_usage();
        return ExitCode::from(2);
    };
    let Some(path) = args.next() else {
        schedule_usage();
        return ExitCode::from(2);
    };
    match action.as_str() {
        "list" => {
            let json = match args.next().as_deref() {
                None => false,
                Some("--json") => true,
                _ => {
                    schedule_usage();
                    return ExitCode::from(2);
                }
            };
            if args.next().is_some() {
                schedule_usage();
                return ExitCode::from(2);
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            if json {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&json!({
                        "schema_version": 1,
                        "schedules": program.schedules.iter().map(|schedule| json!({
                            "name": schedule.name,
                            "command": schedule.command,
                            "cron": schedule.cron,
                            "timezone": schedule.timezone,
                            "source_line": schedule.span.line,
                        })).collect::<Vec<_>>(),
                    }))
                    .expect("schedule inventory JSON is serializable")
                );
            } else if program.schedules.is_empty() {
                println!("No schedules declared in {path}");
            } else {
                for schedule in &program.schedules {
                    println!(
                        "{}: {}  {}",
                        schedule.name,
                        schedule.cron,
                        schedule.timezone.as_deref().unwrap_or("UTC (default)")
                    );
                }
            }
            ExitCode::SUCCESS
        }
        "export" => {
            let mut format_seen = false;
            let mut output = None;
            while let Some(argument) = args.next() {
                match argument.as_str() {
                    "--format" if !format_seen => match args.next() {
                        Some(value) if value == "cron" => format_seen = true,
                        _ => {
                            schedule_usage();
                            return ExitCode::from(2);
                        }
                    },
                    "--output" if output.is_none() => match args.next() {
                        Some(value) if !value.is_empty() => output = Some(value),
                        _ => {
                            schedule_usage();
                            return ExitCode::from(2);
                        }
                    },
                    _ => {
                        schedule_usage();
                        return ExitCode::from(2);
                    }
                }
            }
            let Ok(program) = validate(&path) else {
                return ExitCode::from(1);
            };
            let cron = match render_schedule_export(&path, &program) {
                Ok(cron) => cron,
                Err(error) => {
                    eprintln!("error[E-TASK-003]: {error}");
                    return ExitCode::from(1);
                }
            };
            if let Some(output) = output {
                let project_root = match std::path::Path::new(&path).canonicalize().map(|entry| {
                    entry
                        .parent()
                        .unwrap_or(std::path::Path::new("."))
                        .to_path_buf()
                }) {
                    Ok(root) => root,
                    Err(error) => {
                        eprintln!("error[E-TASK-003]: cannot resolve project root: {error}");
                        return ExitCode::from(1);
                    }
                };
                match write_schedule_export(&project_root, &output, cron.as_bytes()) {
                    Ok(path) => eprintln!(
                        "Cron preview written to {}. Review it before installing; Zelyra did not install or enable a scheduler.",
                        path.display()
                    ),
                    Err(message) => {
                        eprintln!("error[E-TASK-004]: {message}");
                        return ExitCode::from(1);
                    }
                }
            } else {
                print!("{cron}");
                eprintln!("Review this cron preview before installing it. Zelyra did not install or enable a scheduler.");
            }
            ExitCode::SUCCESS
        }
        _ => {
            schedule_usage();
            ExitCode::from(2)
        }
    }
}

/// Prepare schedules after an explicit project database/schema setup. Mail
/// schedules need the outbox table; cron export is a project-owned artifact
/// and is refreshed only when Zelyra owns the previous generated file.
pub(super) fn setup_declared_schedules(
    entry_path: &std::path::Path,
) -> Result<Vec<String>, String> {
    if !entry_path.is_file() {
        return Ok(Vec::new());
    }
    let entry_metadata = std::fs::symlink_metadata(entry_path).map_err(|error| {
        format!(
            "cannot inspect project entry `{}`: {error}",
            entry_path.display()
        )
    })?;
    if entry_metadata.file_type().is_symlink() {
        return Err(format!(
            "refusing to prepare schedules from symlinked entry `{}`",
            entry_path.display()
        ));
    }
    let project_root = entry_path
        .parent()
        .ok_or_else(|| "project entry has no parent directory".to_owned())?
        .canonicalize()
        .map_err(|error| format!("cannot resolve project root: {error}"))?;
    let canonical_entry = entry_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve project entry: {error}"))?;
    if canonical_entry.parent() != Some(project_root.as_path()) {
        return Err("project entry resolves outside the configured project root".into());
    }
    let entry = entry_path.to_string_lossy().into_owned();
    let loaded = load_project(&entry).map_err(|_| {
        "cannot prepare schedules because the project did not pass compiler validation".to_owned()
    })?;
    let program = loaded.program;
    if program.schedules.is_empty() {
        return Ok(Vec::new());
    }

    let mut messages = Vec::new();
    let has_mail_schedule = program.schedules.iter().any(|schedule| {
        let Some(command) = program
            .commands
            .iter()
            .find(|command| command.name == schedule.command)
        else {
            return false;
        };
        program
            .functions
            .iter()
            .find(|function| function.name == command.handler)
            .is_some_and(|function| {
                function
                    .capabilities
                    .iter()
                    .any(|capability| capability == "Email")
            })
    });
    if has_mail_schedule {
        let schema = build_schema(&program).map_err(|errors| {
            format!(
                "cannot prepare the outbox because the project schema is invalid: {}",
                errors
                    .iter()
                    .map(|error| error.message.as_str())
                    .collect::<Vec<_>>()
                    .join("; ")
            )
        })?;
        if schema.backend() != Backend::MariaDb {
            return Err(
                "scheduled email currently requires a MariaDB project because the outbox backend is MariaDB".into(),
            );
        }
        let database_url =
            outbox_cli::project_outbox_database_url(&entry, &schema)?.ok_or_else(|| {
                "scheduled email requires a configured project database URL".to_owned()
            })?;
        zelyra_database::outbox::ensure_mariadb_outbox(&database_url)
            .map_err(|error| format!("could not initialize the scheduled-email outbox: {error}"))?;
        messages.push("scheduled-email outbox is ready (repeat-safe setup)".into());
    }

    let state_directory = project_root.join(".zelyra");
    match std::fs::symlink_metadata(&state_directory) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err(format!(
                "refusing to use non-directory or symlinked scheduler state `{}`",
                state_directory.display()
            ));
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            std::fs::create_dir(&state_directory).map_err(|error| {
                format!(
                    "cannot create scheduler state `{}`: {error}",
                    state_directory.display()
                )
            })?;
        }
        Err(error) => {
            return Err(format!(
                "cannot inspect scheduler state `{}`: {error}",
                state_directory.display()
            ));
        }
    }
    let export_path = state_directory.join("schedules.cron");
    let cron = render_schedule_export(&entry, &program)?;
    let managed_contents = format!("{MANAGED_SCHEDULE_EXPORT_HEADER}\n{cron}");
    match std::fs::symlink_metadata(&export_path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Err(format!(
                "refusing to replace non-file or symlinked schedule export `{}`",
                export_path.display()
            ));
        }
        Ok(_) => {
            let existing = std::fs::read(&export_path).map_err(|error| {
                format!(
                    "cannot read schedule export `{}`: {error}",
                    export_path.display()
                )
            })?;
            if !existing.starts_with(MANAGED_SCHEDULE_EXPORT_HEADER.as_bytes()) {
                return Err(format!(
                    "schedule export `{}` exists but is not managed by Zelyra; it was left unchanged",
                    export_path.display()
                ));
            }
            if existing == managed_contents.as_bytes() {
                messages.push(format!(
                    "schedule export is current at {}",
                    export_path.display()
                ));
            } else {
                atomic_replace_managed_schedule_export(&export_path, managed_contents.as_bytes())?;
                messages.push(format!(
                    "schedule export refreshed at {}",
                    export_path.display()
                ));
            }
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            create_managed_schedule_export(&export_path, managed_contents.as_bytes())?;
            messages.push(format!(
                "schedule export generated at {} (review and activate it on an external cron host if needed)",
                export_path.display()
            ));
        }
        Err(error) => {
            return Err(format!(
                "cannot inspect schedule export `{}`: {error}",
                export_path.display()
            ));
        }
    }
    Ok(messages)
}

fn render_schedule_export(path: &str, program: &zelyra_ast::Program) -> Result<String, String> {
    let absolute_entry = std::path::Path::new(path)
        .canonicalize()
        .map_err(|error| format!("cannot resolve `{path}`: {error}"))?;
    let project_root = absolute_entry.parent().unwrap_or(std::path::Path::new("."));
    let executable =
        env::current_exe().map_err(|error| format!("cannot locate Zelyra executable: {error}"))?;
    if absolute_entry
        .as_os_str()
        .to_string_lossy()
        .chars()
        .any(char::is_control)
        || executable
            .as_os_str()
            .to_string_lossy()
            .chars()
            .any(char::is_control)
    {
        return Err("cron export cannot safely represent control characters in the project or executable path".into());
    }
    let mut cron = String::new();
    for schedule in &program.schedules {
        let command = program
            .commands
            .iter()
            .find(|command| command.name == schedule.command)
            .expect("compiler validates schedule references");
        let timezone = schedule.timezone.as_deref().unwrap_or("UTC");
        writeln!(cron, "# Zelyra schedule: {}", schedule.name)
            .expect("writing to a String cannot fail");
        writeln!(cron, "CRON_TZ={timezone}").expect("writing to a String cannot fail");
        writeln!(
            cron,
            "{} cd {} && {} run {} --entry {}",
            schedule.cron,
            shell_quote(&project_root.to_string_lossy()),
            shell_quote(&executable.to_string_lossy()),
            shell_quote(&absolute_entry.to_string_lossy()),
            shell_quote(&command.handler)
        )
        .expect("writing to a String cannot fail");
        cron.push('\n');
    }
    Ok(cron)
}

fn create_managed_schedule_export(path: &std::path::Path, contents: &[u8]) -> Result<(), String> {
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options.open(path).map_err(|error| {
        format!(
            "cannot create schedule export `{}`: {error}",
            path.display()
        )
    })?;
    if let Err(error) = file.write_all(contents).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = std::fs::remove_file(path);
        return Err(format!("cannot write schedule export: {error}"));
    }
    Ok(())
}

fn atomic_replace_managed_schedule_export(
    path: &std::path::Path,
    contents: &[u8],
) -> Result<(), String> {
    let parent = path
        .parent()
        .ok_or_else(|| "schedule export has no parent directory".to_owned())?;
    let temporary = parent.join(format!(".schedules-{}.tmp", std::process::id()));
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options
        .open(&temporary)
        .map_err(|error| format!("cannot create schedule export replacement: {error}"))?;
    if let Err(error) = file.write_all(contents).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = std::fs::remove_file(&temporary);
        return Err(format!("cannot write schedule export replacement: {error}"));
    }
    drop(file);
    #[cfg(windows)]
    {
        let backup = parent.join(format!(".schedules-{}.bak", std::process::id()));
        if backup.exists() {
            let _ = std::fs::remove_file(&temporary);
            return Err("a prior schedule export replacement backup needs recovery".into());
        }
        if let Err(error) = std::fs::rename(path, &backup) {
            let _ = std::fs::remove_file(&temporary);
            return Err(format!("cannot preserve previous schedule export: {error}"));
        }
        if let Err(error) = std::fs::rename(&temporary, path) {
            let _ = std::fs::rename(&backup, path);
            let _ = std::fs::remove_file(&temporary);
            return Err(format!("cannot replace schedule export: {error}"));
        }
        std::fs::remove_file(backup)
            .map_err(|error| format!("cannot remove schedule export backup: {error}"))?;
    }
    #[cfg(not(windows))]
    std::fs::rename(&temporary, path)
        .map_err(|error| format!("cannot atomically replace schedule export: {error}"))?;
    Ok(())
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn write_schedule_export(
    project_root: &std::path::Path,
    relative_path: &str,
    contents: &[u8],
) -> Result<PathBuf, String> {
    let relative = std::path::Path::new(relative_path);
    if relative_path.chars().any(char::is_control)
        || relative.is_absolute()
        || relative
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(
            "--output must be a project-relative path without `.` or `..` components".into(),
        );
    }
    let file_name = relative
        .file_name()
        .ok_or_else(|| "--output must name a file".to_owned())?;
    let parent = project_root.join(
        relative
            .parent()
            .unwrap_or_else(|| std::path::Path::new("")),
    );
    let canonical_parent = parent.canonicalize().map_err(|error| {
        format!(
            "cannot resolve output directory `{}`: {error}",
            parent.display()
        )
    })?;
    if !canonical_parent.starts_with(project_root) {
        return Err("--output directory resolves outside the project".into());
    }
    let destination = canonical_parent.join(file_name);
    match fs::symlink_metadata(&destination) {
        Ok(_) => {
            return Err(format!(
                "refusing to replace existing output `{}`",
                destination.display()
            ))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(format!(
                "cannot inspect output `{}`: {error}",
                destination.display()
            ))
        }
    }
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&destination)
        .map_err(|error| format!("cannot create output `{}`: {error}", destination.display()))?;
    if let Err(error) = file.write_all(contents).and_then(|()| file.sync_all()) {
        drop(file);
        let _ = fs::remove_file(&destination);
        return Err(format!(
            "cannot write output `{}`: {error}",
            destination.display()
        ));
    }
    Ok(destination)
}

fn task_usage() {
    eprintln!("Usage: zelyra task list <main.zyl> [--json] | task run <main.zyl> <command> [--args '<JSON-array>'] [--max-steps <n>]");
}

fn schedule_usage() {
    eprintln!("Usage: zelyra schedule list <main.zyl> [--json] | schedule export <main.zyl> [--format cron] [--output <project-relative-file>]");
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn setup_generates_schedule_export_once_for_checked_project() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let project = std::env::temp_dir().join(format!(
            "zelyra-schedule-setup-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir(&project).expect("create isolated project directory");
        let entry = project.join("main.zyl");
        std::fs::write(
            &entry,
            r#"
command weekly_email {
    handler: send_weekly_email
}
schedule weekly_email {
    command: weekly_email
    cron: "0 12 * * 6"
    timezone: "Europe/Berlin"
}
fn send_weekly_email() { }
fn main() { }
"#,
        )
        .expect("write valid scheduled project");

        let first = setup_declared_schedules(&entry).expect("prepare checked schedule");
        assert_eq!(first.len(), 1);
        assert!(first[0].contains("schedule export generated"));
        let export = project.join(".zelyra/schedules.cron");
        let generated = std::fs::read_to_string(&export).expect("read generated cron export");
        assert!(generated.contains("0 12 * * 6"));
        assert!(generated.contains("Zelyra schedule: weekly_email"));
        assert!(generated.starts_with(MANAGED_SCHEDULE_EXPORT_HEADER));

        let second = setup_declared_schedules(&entry).expect("repeat setup safely");
        assert_eq!(second.len(), 1);
        assert!(second[0].contains("schedule export is current"));
        assert_eq!(std::fs::read_to_string(&export).unwrap(), generated);

        let source = std::fs::read_to_string(&entry).unwrap();
        std::fs::write(&entry, source.replace("0 12 * * 6", "5 12 * * 6"))
            .expect("update schedule declaration");
        let third = setup_declared_schedules(&entry).expect("refresh changed schedule");
        assert!(third[0].contains("schedule export refreshed"));
        let refreshed = std::fs::read_to_string(&export).expect("read refreshed cron export");
        assert!(refreshed.contains("5 12 * * 6"));
        assert!(!refreshed.contains("0 12 * * 6"));

        std::fs::remove_dir_all(project).expect("remove isolated project");
    }

    #[cfg(unix)]
    #[test]
    fn setup_refuses_symlinked_schedule_state_directory() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let parent = std::env::temp_dir().join(format!(
            "zelyra-schedule-symlink-{}-{nonce}",
            std::process::id()
        ));
        let project = parent.join("project");
        let outside = parent.join("outside");
        std::fs::create_dir_all(&project).expect("create isolated project directory");
        std::fs::create_dir(&outside).expect("create outside directory");
        std::fs::write(
            project.join("main.zyl"),
            "command daily { handler: run_daily } schedule daily { command: daily cron: \"0 0 * * *\" } fn run_daily() { } fn main() { }",
        )
        .expect("write valid scheduled project");
        std::os::unix::fs::symlink(&outside, project.join(".zelyra"))
            .expect("create state-directory symlink");

        let error = setup_declared_schedules(&project.join("main.zyl"))
            .expect_err("reject symlinked scheduler state");
        assert!(error.contains("symlinked scheduler state"));
        assert!(std::fs::read_dir(&outside)
            .expect("read outside directory")
            .next()
            .is_none());

        std::fs::remove_dir_all(parent).expect("remove isolated project tree");
    }

    #[test]
    fn setup_preserves_an_unmanaged_schedule_export() {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock follows Unix epoch")
            .as_nanos();
        let project = std::env::temp_dir().join(format!(
            "zelyra-schedule-owned-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir_all(project.join(".zelyra")).expect("create project state");
        let entry = project.join("main.zyl");
        std::fs::write(
            &entry,
            "command daily { handler: run_daily } schedule daily { command: daily cron: \"0 0 * * *\" } fn run_daily() { } fn main() { }",
        )
        .expect("write valid scheduled project");
        let export = project.join(".zelyra/schedules.cron");
        std::fs::write(&export, "# user-managed\nkeep this file\n")
            .expect("write user-owned schedule file");

        let error =
            setup_declared_schedules(&entry).expect_err("do not replace a user-managed export");
        assert!(error.contains("not managed by Zelyra"));
        assert_eq!(
            std::fs::read_to_string(&export).unwrap(),
            "# user-managed\nkeep this file\n"
        );

        std::fs::remove_dir_all(project).expect("remove isolated project");
    }
}
